--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `email` varchar(150) CHARACTER SET utf8mb4 NOT NULL DEFAULT '',
  `username` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 NOT NULL DEFAULT '',
  `phone` varchar(25) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatar` varchar(150) CHARACTER SET utf8mb4 DEFAULT 'avartar10.png',
  `password` varchar(150) CHARACTER SET utf8mb4 NOT NULL DEFAULT '',
  `role_id` bigint(20) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `token` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL,
  `is_active` enum('Y','N') CHARACTER SET utf8mb4 NOT NULL DEFAULT 'Y',
  `is_delete` enum('Y','N') CHARACTER SET utf8mb4 NOT NULL DEFAULT 'N',
